using System;

namespace Proof.Node.WebServer
{
    public static class App
    {
        public static double readPort(double defaultPort)
        {
            string? configured = Tsonic.CSharp.Node.process.env["PROOF_PORT"];
            if (configured is null)
            {
                return defaultPort;
            }
            double port = Tsonic.CSharp.Js.Globals.Number(configured);
            if (!Tsonic.CSharp.Js.Number.isInteger(port) || port < 1 || port > 65535)
            {
                throw new System.InvalidOperationException("PROOF_PORT must be an integer from 1 through 65535.");
            }
            return port;
        }
        public static void main()
        {
            double port = readPort(8765);
            Tsonic.CSharp.Node.Http.Server server = Tsonic.CSharp.Node.Http.http.createServer((Tsonic.CSharp.Node.Http.IncomingMessage req, Tsonic.CSharp.Node.Http.ServerResponse res) =>
            {
                Tsonic.CSharp.Js.console.log($"{req.method} {req.url}");
                res.setHeader("Content-Type", "text/plain");
                res.writeHead(200, "OK");
                res.end("Hello from Tsonic!");
            });
            server.listen(port, () =>
            {
                Tsonic.CSharp.Js.console.log($"Server running at http://localhost:{port}/");
            });
