import { run } from "./server.js";

export function main(): void {
  run();
}

main();

import {
  DbContext,
  type DbContextOptions,
  type DbSet,
} from "@tsonic/dotnet/Microsoft.EntityFrameworkCore.js";

import type { CommentEntity, PostEntity } from "./entities.js";

export class BlogDbContext extends DbContext {
  get posts(): DbSet<PostEntity> {
    return this.Set<PostEntity>();
  }

  get comments(): DbSet<CommentEntity> {
    return this.Set<CommentEntity>();
  }

  constructor(options: DbContextOptions) {
    super(options);
  }
}

import type { int } from "@tsonic/csharp/types.js";
import type { DateTime } from "@tsonic/dotnet/System.js";
import type { List } from "@tsonic/dotnet/System.Collections.Generic.js";

export interface PostInput {
  title: string;
  content: string;
}

export interface CommentCreateInput {
  author: string;
  body: string;
}

export interface ErrorResponse {
  error: string;
}

export interface HealthResponse {
  ok: boolean;
}

export interface PostDto {
  id: int;
  title: string;
  content: string;
  createdAt: DateTime;
  updatedAt: DateTime;
}

export interface CommentDto {
  id: int;
  postId: int;
  author: string;
  body: string;
  createdAt: DateTime;
}

export interface PostDetailDto extends PostDto {
  comments: List<CommentDto>;
}

import type { int } from "@tsonic/csharp/types.js";
import { DateTime } from "@tsonic/dotnet/System.js";

interface PostEntityProperties {
  Id: int;
  Title: string;
  Content: string;
  CreatedAt: DateTime;
  UpdatedAt: DateTime;
}

interface CommentEntityProperties {
  Id: int;
  PostId: int;
  Author: string;
  Body: string;
  CreatedAt: DateTime;
}

export class PostEntity implements PostEntityProperties {
  Id: int = 0;
  Title = "";
  Content = "";
  CreatedAt: DateTime = DateTime.MinValue;
  UpdatedAt: DateTime = DateTime.MinValue;
}

export class CommentEntity implements CommentEntityProperties {
  Id: int = 0;
  PostId: int = 0;
  Author = "";
  Body = "";
  CreatedAt: DateTime = DateTime.MinValue;
}

import type { CommentEntity, PostEntity } from "./entities.js";
import type { CommentDto, PostDto } from "./dtos.js";

export const toPostDto = (p: PostEntity): PostDto => ({
  id: p.Id,
  title: p.Title,
  content: p.Content,
  createdAt: p.CreatedAt,
  updatedAt: p.UpdatedAt,
});

export const toCommentDto = (c: CommentEntity): CommentDto => ({
  id: c.Id,
  postId: c.PostId,
  author: c.Author,
  body: c.Body,
  createdAt: c.CreatedAt,
});

import { Environment } from "@tsonic/dotnet/System.js";

import {
  DbContextOptionsBuilder,
  SqliteDbContextOptionsBuilderExtensions,
  type DbContextOptions,
} from "@tsonic/dotnet/Microsoft.EntityFrameworkCore.js";

export const DB_PATH = Environment.GetEnvironmentVariable("TS_PUDDING_DB") ?? "app.db";

export const createDbOptions = (dbPath: string): DbContextOptions => {
  const optionsBuilder = new DbContextOptionsBuilder();
  const connectionString = `Data Source=${dbPath}`;
  SqliteDbContextOptionsBuilderExtensions.UseSqlite(optionsBuilder, connectionString);
  return optionsBuilder.Options;
};

export const DB_OPTIONS = createDbOptions(DB_PATH);

import { DateTime } from "@tsonic/dotnet/System.js";
import { Queryable } from "@tsonic/dotnet/System.Linq.js";

import { BlogDbContext } from "./context.js";
import { PostEntity } from "./entities.js";
import { DB_OPTIONS } from "./options.js";

export const ensureCreatedAndSeed = (): void => {
  const db = new BlogDbContext(DB_OPTIONS);
  try {
    db.Database.EnsureCreated();

    if (!Queryable.Any(db.posts.AsQueryable())) {
      const now = DateTime.UtcNow;
      const post = new PostEntity();
      post.Title = "Welcome to Tsonic";
      post.Content = "This blog is backed by EF Core + SQLite.";
      post.CreatedAt = now;
      post.UpdatedAt = now;
      db.posts.Add(post);
      db.SaveChanges();
    }
  } finally {
    db.Dispose();
  }
};

import type { int } from "@tsonic/csharp/types.js";
import { Int32 } from "@tsonic/dotnet/System.js";
import { StreamReader } from "@tsonic/dotnet/System.IO.js";
import { Encoding } from "@tsonic/dotnet/System.Text.js";
import { JsonSerializer } from "@tsonic/dotnet/System.Text.Json.js";
import { Task } from "@tsonic/dotnet/System.Threading.Tasks.js";
import { out } from "@tsonic/csharp/lang.js";

import {
  HttpResponseWritingExtensions,
  type HttpContext,
  type HttpResponse,
} from "@tsonic/dotnet/Microsoft.AspNetCore.Http.js";

import type { ErrorResponse } from "../db/dtos.js";

export const serializeError = (message: string): string =>
  JsonSerializer.Serialize<ErrorResponse>({ error: message });

export const readRequestBodyAsync = (ctx: HttpContext): Task<string> => {
  const reader = new StreamReader(ctx.Request.Body, Encoding.UTF8);
  return reader.ReadToEndAsync().ContinueWith<string>((t, _state) => {
    try {
      return t.Result;
    } finally {
      reader.Close();
    }
  }, undefined);
};

export const writeText = (response: HttpResponse, statusCode: int, contentType: string, body: string): Task => {
  response.StatusCode = statusCode;
  response.ContentType = contentType;
  // HTTP 204 (No Content) and 304 (Not Modified) must not include a response body.
  // Kestrel throws if we attempt to write a body for these status codes.
  if (statusCode === 204 || statusCode === 304 || (statusCode >= 100 && statusCode < 200)) {
    return Task.CompletedTask;
  }
  return HttpResponseWritingExtensions.WriteAsync(response, body);
};

export const writeJson = (response: HttpResponse, statusCode: int, body: string): Task =>
  writeText(response, statusCode, "application/json", body);

export const getPath = (ctx: HttpContext): string => ctx.Request.Path.ToString();

export const parsePostIdFromPath = (path: string): int | undefined => {
  const parts = path.Split("/");
  if (
    (parts.Length !== 4 && parts.Length !== 5) ||
    parts[0] !== "" ||
    parts[1] !== "api" ||
    parts[2] !== "posts" ||
    (parts.Length === 5 && parts[4] !== "comments")
  ) {
    return undefined;
  }
  const idStr = parts[3];
  if (idStr === "") return undefined;
  let id: int = 0;
  return Int32.TryParse(idStr, out(id)) ? id : undefined;
};

export const parsePostIdRequired = (ctx: HttpContext): int | undefined =>
  parsePostIdFromPath(getPath(ctx));

import { JsonDocument, JsonException, JsonValueKind } from "@tsonic/dotnet/System.Text.Json.js";

import type { CommentCreateInput, PostInput } from "../db/dtos.js";

function tryParseJsonDocument(json: string): JsonDocument | undefined {
  try {
    return JsonDocument.Parse(json);
  } catch (error) {
    if (!(error instanceof JsonException)) throw error;
    return undefined;
  }
}

export function parsePostInput(json: string): PostInput | undefined {
  const document = tryParseJsonDocument(json);
  if (document === undefined) return undefined;
  try {
    const root = document.RootElement;
    if (root.ValueKind !== JsonValueKind.Object) return undefined;
    let title: string | undefined = undefined;
    let content: string | undefined = undefined;
    const properties = root.EnumerateObject().GetEnumerator();
    while (properties.MoveNext()) {
      const property = properties.Current;
      if (property.Name === "title" && property.Value.ValueKind === JsonValueKind.String) {
        title = property.Value.GetString();
      } else if (property.Name === "content" && property.Value.ValueKind === JsonValueKind.String) {
        content = property.Value.GetString();
      }
    }
    if (title === undefined || content === undefined) return undefined;
    return { title, content };
  } finally {
    document.Dispose();
  }
}

export function parseCommentCreate(json: string): CommentCreateInput | undefined {
  const document = tryParseJsonDocument(json);
  if (document === undefined) return undefined;
  try {
    const root = document.RootElement;
    if (root.ValueKind !== JsonValueKind.Object) return undefined;
    let author: string | undefined = undefined;
    let body: string | undefined = undefined;
    const properties = root.EnumerateObject().GetEnumerator();
    while (properties.MoveNext()) {
      const property = properties.Current;
      if (property.Name === "author" && property.Value.ValueKind === JsonValueKind.String) {
        author = property.Value.GetString();
      } else if (property.Name === "body" && property.Value.ValueKind === JsonValueKind.String) {
        body = property.Value.GetString();
      }
    }
    if (author === undefined || body === undefined) return undefined;
    return { author, body };
  } finally {
    document.Dispose();
  }
}

import { DateTime } from "@tsonic/dotnet/System.js";
import { JsonSerializer } from "@tsonic/dotnet/System.Text.Json.js";
import { List } from "@tsonic/dotnet/System.Collections.Generic.js";
import { Queryable } from "@tsonic/dotnet/System.Linq.js";
import { TaskExtensions, type Task } from "@tsonic/dotnet/System.Threading.Tasks.js";
import { EntityFrameworkQueryableExtensions } from "@tsonic/dotnet/Microsoft.EntityFrameworkCore.js";

import type { HttpContext } from "@tsonic/dotnet/Microsoft.AspNetCore.Http.js";

import type { CommentDto } from "../db/dtos.js";
import { CommentEntity } from "../db/entities.js";
import { BlogDbContext } from "../db/context.js";
import { DB_OPTIONS } from "../db/options.js";
import { toCommentDto } from "../db/mappers.js";
import { parsePostIdRequired, readRequestBodyAsync, serializeError, writeJson } from "../http/http-helpers.js";
import { parseCommentCreate } from "../http/json-input.js";

export const handleListComments = (ctx: HttpContext): Task => {
  const postIdRaw = parsePostIdRequired(ctx);
  if (postIdRaw === undefined) {
    return writeJson(ctx.Response, 400, serializeError("Missing post id"));
  }
  const postId = postIdRaw;

  const db = new BlogDbContext(DB_OPTIONS);
  try {
    const query = Queryable.OrderByDescending<CommentEntity, DateTime>(
      db.comments.AsQueryable(),
      (c: CommentEntity): DateTime => c.CreatedAt
    );
    const filtered = Queryable.Where(query, (c: CommentEntity) => c.PostId === postId);
    return TaskExtensions.Unwrap(
      EntityFrameworkQueryableExtensions.ToArrayAsync(filtered).ContinueWith<Task>((t, _state) => {
        try {
          const list = t.Result;
          const dtos = new List<CommentDto>();
          for (let i = 0; i < list.Length; i++) {
            dtos.Add(toCommentDto(list[i]));
          }
          return writeJson(ctx.Response, 200, JsonSerializer.Serialize<List<CommentDto>>(dtos));
        } finally {
          db.Dispose();
        }
      }, undefined)
    );
  } catch (error) {
    db.Dispose();
    throw error;
  }
};

export const handleCreateComment = (ctx: HttpContext): Task => {
  const postIdRaw = parsePostIdRequired(ctx);
  if (postIdRaw === undefined) {
    return writeJson(ctx.Response, 400, serializeError("Missing post id"));
  }
  const postId = postIdRaw;

  return TaskExtensions.Unwrap(
    readRequestBodyAsync(ctx).ContinueWith<Task>((t: Task<string>, _state) => {
      const input = parseCommentCreate(t.Result);
      if (input === undefined) {
        return writeJson(
          ctx.Response,
          400,
          serializeError("Invalid JSON: expected {\"author\": \"...\", \"body\": \"...\"}")
        );
      }
      if (input.body.Trim() === "") {
        return writeJson(ctx.Response, 400, serializeError("Comment body is required"));
      }

      let payload: string | undefined = undefined;
      const db = new BlogDbContext(DB_OPTIONS);
      try {
        const post = db.posts.Find(postId);
        if (post !== undefined) {
          const comment = new CommentEntity();
          comment.PostId = postId;
          comment.Author = input.author.Trim() === "" ? "Anonymous" : input.author;
          comment.Body = input.body;
          comment.CreatedAt = DateTime.UtcNow;
          db.comments.Add(comment);
          db.SaveChanges();
          payload = JsonSerializer.Serialize<CommentDto>(toCommentDto(comment));
        }
      } finally {
        db.Dispose();
      }

      if (payload === undefined) {
        return writeJson(ctx.Response, 404, serializeError("Post not found"));
      }

      return writeJson(ctx.Response, 201, payload);
    }, undefined)
  );
};

import { JsonSerializer } from "@tsonic/dotnet/System.Text.Json.js";
import type { Task } from "@tsonic/dotnet/System.Threading.Tasks.js";

import type { HttpContext } from "@tsonic/dotnet/Microsoft.AspNetCore.Http.js";

import type { HealthResponse } from "../db/dtos.js";
import { writeJson } from "../http/http-helpers.js";

export const handleHealth = (ctx: HttpContext): Task => {
  const payload = JsonSerializer.Serialize<HealthResponse>({ ok: true });
  return writeJson(ctx.Response, 200, payload);
};

import type { Task } from "@tsonic/dotnet/System.Threading.Tasks.js";

import type { HttpContext } from "@tsonic/dotnet/Microsoft.AspNetCore.Http.js";

import { writeText } from "../http/http-helpers.js";
import { INDEX_HTML } from "../ui/index-html.js";

export const handleIndex = (ctx: HttpContext): Task =>
  writeText(ctx.Response, 200, "text/html; charset=utf-8", INDEX_HTML);

import { DateTime } from "@tsonic/dotnet/System.js";
import { JsonSerializer } from "@tsonic/dotnet/System.Text.Json.js";
import { List } from "@tsonic/dotnet/System.Collections.Generic.js";
import { Queryable } from "@tsonic/dotnet/System.Linq.js";
import { TaskExtensions, type Task } from "@tsonic/dotnet/System.Threading.Tasks.js";
import { EntityFrameworkQueryableExtensions } from "@tsonic/dotnet/Microsoft.EntityFrameworkCore.js";

import type { HttpContext } from "@tsonic/dotnet/Microsoft.AspNetCore.Http.js";

import type { CommentDto, PostDetailDto, PostDto } from "../db/dtos.js";
import { PostEntity } from "../db/entities.js";
import type { CommentEntity } from "../db/entities.js";
import { BlogDbContext } from "../db/context.js";
import { DB_OPTIONS } from "../db/options.js";
import { toCommentDto, toPostDto } from "../db/mappers.js";
import { parsePostIdRequired, readRequestBodyAsync, serializeError, writeJson } from "../http/http-helpers.js";
import { parsePostInput } from "../http/json-input.js";

export const handleListPosts = (ctx: HttpContext): Task => {
  const db = new BlogDbContext(DB_OPTIONS);
  try {
    const query = Queryable.OrderByDescending(db.posts.AsQueryable(), (p) => p.CreatedAt);
    return TaskExtensions.Unwrap(
      EntityFrameworkQueryableExtensions.ToArrayAsync(query).ContinueWith<Task>((t, _state) => {
        try {
          const posts = t.Result;
          const result = new List<PostDto>();
          for (let i = 0; i < posts.Length; i++) {
            result.Add(toPostDto(posts[i]));
          }
          return writeJson(ctx.Response, 200, JsonSerializer.Serialize<List<PostDto>>(result));
        } finally {
          db.Dispose();
        }
      }, undefined)
    );
  } catch (error) {
    db.Dispose();
    throw error;
  }
};

export const handleGetPost = (ctx: HttpContext): Task => {
  const postIdRaw = parsePostIdRequired(ctx);
  if (postIdRaw === undefined) {
    return writeJson(ctx.Response, 400, serializeError("Missing post id"));
  }
  const postId = postIdRaw;

  const db = new BlogDbContext(DB_OPTIONS);
  try {
    const post = db.posts.Find(postId);
    if (post === undefined) {
      db.Dispose();
      return writeJson(ctx.Response, 404, serializeError("Post not found"));
    }
    const commentsQuery = Queryable.OrderByDescending<CommentEntity, DateTime>(
      db.comments.AsQueryable(),
      (c: CommentEntity): DateTime => c.CreatedAt
    );
    const commentsForPost = Queryable.Where(commentsQuery, (c: CommentEntity) => c.PostId === postId);
    return TaskExtensions.Unwrap(
      EntityFrameworkQueryableExtensions.ToArrayAsync(commentsForPost).ContinueWith<Task>((t, _state) => {
        try {
          const comments = t.Result;
          const commentDtos = new List<CommentDto>();
          for (let i = 0; i < comments.Length; i++) {
            commentDtos.Add(toCommentDto(comments[i]));
          }
          const dto: PostDetailDto = {
            id: post.Id,
            title: post.Title,
            content: post.Content,
            createdAt: post.CreatedAt,
            updatedAt: post.UpdatedAt,
            comments: commentDtos,
          };
          return writeJson(ctx.Response, 200, JsonSerializer.Serialize<PostDetailDto>(dto));
        } finally {
          db.Dispose();
        }
      }, undefined)
    );
  } catch (error) {
    db.Dispose();
    throw error;
  }
};

export const handleCreatePost = (ctx: HttpContext): Task =>
  TaskExtensions.Unwrap(
    readRequestBodyAsync(ctx).ContinueWith<Task>((t: Task<string>, _state) => {
      const input = parsePostInput(t.Result);
      if (input === undefined) {
        return writeJson(
          ctx.Response,
          400,
          serializeError("Invalid JSON: expected {\"title\": \"...\", \"content\": \"...\"}")
        );
      }

      let payload = "";
      const db = new BlogDbContext(DB_OPTIONS);
      try {
        const now = DateTime.UtcNow;
        const post = new PostEntity();
        post.Title = input.title;
        post.Content = input.content;
        post.CreatedAt = now;
        post.UpdatedAt = now;
        db.posts.Add(post);
        db.SaveChanges();
        payload = JsonSerializer.Serialize<PostDto>(toPostDto(post));
      } finally {
        db.Dispose();
      }

      return writeJson(ctx.Response, 201, payload);
    }, undefined)
  );

export const handleUpdatePost = (ctx: HttpContext): Task => {
  const postIdRaw = parsePostIdRequired(ctx);
  if (postIdRaw === undefined) {
    return writeJson(ctx.Response, 400, serializeError("Missing post id"));
  }
  const postId = postIdRaw;

  return TaskExtensions.Unwrap(
    readRequestBodyAsync(ctx).ContinueWith<Task>((t: Task<string>, _state) => {
      const input = parsePostInput(t.Result);
