  check(readByte(byte_ptr()) === 23);

  const duplicated = duplicate(8);
  check(duplicated.pop() === 8);
  check(duplicated.pop() === 8);
  check(duplicated.is_empty());
  check(!singleton_map(10).is_empty());
}

